def binary_search(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo < len(a) and a[lo] == x

assert binary_search([20, 40, 70, 90], 90) is True
assert binary_search([90, 20, 70, 40], 90) is False

def binary_search_steps(n, target):
    lo, hi = 0, n - 1
    steps = 0
    while lo <= hi:
        steps += 1
        mid = (lo + hi) // 2
        if mid == target:
            return steps
        if mid < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return steps

assert binary_search_steps(1_000_000, 0) == 20

